package warehouse;

import static readcode.Assert.*;

public class StockServiceTest {
    private StockRepository repo;
    private StockService service;

    public void setUp() {
        repo = new StockRepository();
        service = new StockService(repo);
        repo.insert("LAMP-1", 100, 1L);
    }

    public void testAdjustWithMatchingVersionBumpsVersion() {
        StockRecord saved = service.adjust("LAMP-1", -10, 1);
        assertEquals(90, saved.onHand());
        assertEquals(2L, saved.version().longValue());
    }

    public void testStaleVersionIsRejected() {
        service.adjust("LAMP-1", -10, 1);
        assertThrows(StockService.StaleVersionException.class, () -> service.adjust("LAMP-1", -5, 1));
        assertEquals(90, repo.find("LAMP-1").orElseThrow().onHand(), "rejected edit must not change stock");
    }

    public void testCannotGoNegative() {
        assertThrows(StockService.InsufficientStockException.class, () -> service.adjust("LAMP-1", -101, 1));
    }

    public void testMatchingVersionAbove127IsAccepted() {
        repo.insert("BUSY-1", 50, 500L);
        StockRecord saved = service.adjust("BUSY-1", 5, 500);
        assertEquals(55, saved.onHand(), "a correct If-Match on a heavily edited SKU must be accepted");
        assertEquals(501L, saved.version().longValue());
    }

    public void testStaleVersionAbove127IsStillRejected() {
        repo.insert("BUSY-1", 50, 500L);
        assertThrows(StockService.StaleVersionException.class, () -> service.adjust("BUSY-1", 5, 499));
    }

    public void testClientFollowingReturnedVersionsForManyEdits() {
        long version = 1;
        int edits = 0;
        try {
            for (; edits < 200; edits++) {
                version = service.adjust("LAMP-1", 1, version).version();
            }
        } catch (StockService.StaleVersionException e) {
            System.out.println("rejected at edit #" + (edits + 1) + " with version " + version);
            fail("valid edit #" + (edits + 1) + " (version " + version + ") was rejected as stale");
        }
        assertEquals(300, repo.find("LAMP-1").orElseThrow().onHand());
    }

    public void testRetryPathAppliesDeltas() {
        service.adjustWithRetry("LAMP-1", -1);
        StockRecord saved = service.adjustWithRetry("LAMP-1", -1);
        assertEquals(98, saved.onHand());
        assertEquals(3L, saved.version().longValue());
    }
}
